// Мир: зимняя Terra Nostra ночью. Доска на поляне, дома-«континенты», костёр, баня, столовая, лес, снег.
import * as THREE from 'three';
import { mat, retroize, canvasTex, imgTex, noiseTex, rnd, C, regTex } from './gfx.js?v=1794083424';

export const BT = 0.32;           // верх доски
export const SQ = 1;              // размер клетки

// ---------- склейка статичной геометрии с цветом в вершинах ----------
export class Batch {
  constructor() { this.parts = []; }
  add(geo, color, m) {
    const g = geo.index ? geo.toNonIndexed() : geo.clone();
    if (m) g.applyMatrix4(m);
    const c = new THREE.Color(color); const n = g.attributes.position.count;
    const col = new Float32Array(n * 3); for (let i = 0; i < n; i++) { col[i * 3] = c.r; col[i * 3 + 1] = c.g; col[i * 3 + 2] = c.b; }
    g.setAttribute('color', new THREE.BufferAttribute(col, 3));
    for (const k of Object.keys(g.attributes)) if (!['position', 'normal', 'color'].includes(k)) g.deleteAttribute(k);
    this.parts.push(g); return this;
  }
  box(w, h, d, color, x, y, z, ry = 0, rx = 0, rz = 0) {
    const m = new THREE.Matrix4().compose(new THREE.Vector3(x, y, z), new THREE.Quaternion().setFromEuler(new THREE.Euler(rx, ry, rz)), new THREE.Vector3(1, 1, 1));
    return this.add(new THREE.BoxGeometry(w, h, d), color, m);
  }
  geo(geo, color, x, y, z, ry = 0, s = 1, rx = 0, rz = 0) {
    const m = new THREE.Matrix4().compose(new THREE.Vector3(x, y, z), new THREE.Quaternion().setFromEuler(new THREE.Euler(rx, ry, rz)), new THREE.Vector3(s, s, s));
    return this.add(geo, color, m);
  }
  build(material) {
    let total = 0; for (const p of this.parts) total += p.attributes.position.count;
    const pos = new Float32Array(total * 3), nor = new Float32Array(total * 3), col = new Float32Array(total * 3);
    let o = 0;
    for (const p of this.parts) { pos.set(p.attributes.position.array, o * 3); nor.set(p.attributes.normal.array, o * 3); col.set(p.attributes.color.array, o * 3); o += p.attributes.position.count; }
    const g = new THREE.BufferGeometry();
    g.setAttribute('position', new THREE.BufferAttribute(pos, 3)); g.setAttribute('normal', new THREE.BufferAttribute(nor, 3)); g.setAttribute('color', new THREE.BufferAttribute(col, 3));
    g.computeBoundingSphere();
    return new THREE.Mesh(g, material);
  }
}

function prism(w, h, d) { // двускатная крыша: треугольник по X, длина по Z
  const s = new THREE.Shape(); s.moveTo(-w / 2, 0); s.lineTo(w / 2, 0); s.lineTo(0, h); s.lineTo(-w / 2, 0);
  const g = new THREE.ExtrudeGeometry(s, { depth: d, bevelEnabled: false }); g.translate(0, 0, -d / 2); return g;
}

export function buildWorld(scene, onReady) {
  const R = rnd(7);
  const upd = [];
  const vmat = retroize(new THREE.MeshLambertMaterial({ vertexColors: true }));
  const glow = retroize(new THREE.MeshBasicMaterial({ vertexColors: true }));

  // ---------- небо ----------
  const skyTex = canvasTex(64, 256, (g, w, h) => {
    const gr = g.createLinearGradient(0, 0, 0, h);
    gr.addColorStop(0, '#07061a'); gr.addColorStop(.42, '#1a1438'); gr.addColorStop(.5, '#3a2c5e'); gr.addColorStop(.56, '#2a2244'); gr.addColorStop(1, '#2a2244');
    g.fillStyle = gr; g.fillRect(0, 0, w, h);
    const r = rnd(3);
    for (let i = 0; i < 140; i++) { const y = r() * h * .46; g.fillStyle = r() < .15 ? '#ffe66b' : '#ffffff'; g.globalAlpha = .4 + r() * .6; g.fillRect((r() * w) | 0, y | 0, 1, 1); }
    g.globalAlpha = 1;
  });
  skyTex.wrapS = THREE.RepeatWrapping; skyTex.repeat.set(6, 1);
  const sky = new THREE.Mesh(new THREE.SphereGeometry(95, 24, 12), new THREE.MeshBasicMaterial({ map: skyTex, side: THREE.BackSide, fog: false, depthWrite: false }));
  sky.renderOrder = -10; scene.add(sky);
  const moon = new THREE.Mesh(new THREE.CircleGeometry(4, 10), new THREE.MeshBasicMaterial({ color: '#fff4d6', fog: false }));
  moon.position.set(-38, 34, -60); moon.lookAt(0, 0, 0); scene.add(moon);
  scene.fog = new THREE.Fog('#2a2244', 20, 78);
  scene.background = new THREE.Color('#2a2244');

  // ---------- свет ----------
  scene.add(new THREE.HemisphereLight('#7f86d0', '#2a2238', .7));
  const moonL = new THREE.DirectionalLight('#b8c6ff', .8); moonL.position.set(-20, 30, -12); scene.add(moonL);
  const boardL1 = new THREE.PointLight('#ffd9a8', 16, 0, 1.3); boardL1.position.set(-3, 5.5, 2); scene.add(boardL1);
  const boardL2 = new THREE.PointLight('#ffd9a8', 16, 0, 1.3); boardL2.position.set(3, 5.5, -2); scene.add(boardL2);
  const fireL = new THREE.PointLight('#ff8a3d', 22, 0, 1.4); scene.add(fireL);

  // ---------- земля ----------
  const snowT = noiseTex('#cfd3e8', ['#bcc2dc', '#b0b6d2', '#e2e6f4', '#c4c9e0'], 32, 160, 4, 40);
  const gg = new THREE.PlaneGeometry(200, 200, 50, 50); gg.rotateX(-Math.PI / 2);
  const gp = gg.attributes.position;
  for (let i = 0; i < gp.count; i++) { const x = gp.getX(i), z = gp.getZ(i), d = Math.hypot(x, z); if (d > 12) gp.setY(i, Math.sin(x * .21) * Math.cos(z * .17) * .5 * Math.min(1, (d - 12) / 10)); }
  gg.computeVertexNormals();
  const ground = new THREE.Mesh(gg, mat('#ffffff', { map: snowT })); scene.add(ground);
  // тропинки
  const pathT = noiseTex('#b9b4c9', ['#a59fb8', '#c8c3d6', '#9a93ad'], 16, 60, 9);
  pathT.wrapS = pathT.wrapT = THREE.RepeatWrapping; pathT.repeat.set(1, 12);
  for (const [x, z, ry, len] of [[0, 18, 0, 22], [-9, -6, .9, 14], [9, -6, -.9, 14], [0, -18, 0, 14]]) {
    const p = new THREE.Mesh(new THREE.PlaneGeometry(1.6, len, 1, 8).rotateX(-Math.PI / 2), mat('#ffffff', { map: pathT }));
    p.position.set(x, .02, z); p.rotation.y = ry; scene.add(p);
  }
  // озеро
  const lake = new THREE.Mesh(new THREE.CircleGeometry(16, 14).rotateX(-Math.PI / 2), mat('#1d1a33'));
  lake.position.set(6, .05, 52); scene.add(lake);

  // ---------- доска ----------
  const B = new Batch();
  const wood = '#6b4a3a', woodD = '#4a3128';
  B.box(9.6, BT - .02, 9.6, woodD, 0, (BT - .02) / 2, 0);
  B.box(9.8, .08, 9.8, '#f2f4fb', 0, .04, 0);                         // снежный бортик у подножия
  for (const s of [-1, 1]) { B.box(9.6, .06, .8, wood, 0, BT - .02, s * 4.4); B.box(.8, .06, 8, wood, s * 4.4, BT - .02, 0); }
  // столбы гирлянды
  const poles = [[-5.4, -5.4], [5.4, -5.4], [5.4, 5.4], [-5.4, 5.4]];
  for (const [x, z] of poles) { B.box(.18, 3.6, .18, woodD, x, 1.8, z); B.box(.5, .12, .5, '#ffffff', x, 3.62, z); }
  scene.add(B.build(vmat));

  const boardTex = imgTex('data:image/jpeg;base64,', 256);
  const top = new THREE.Mesh(new THREE.PlaneGeometry(8, 8, 8, 8).rotateX(-Math.PI / 2), mat('#ffffff', { map: boardTex }));
  top.position.y = BT; scene.add(top);
  // буквы и цифры по краю
  const lblTex = (txt, flip) => canvasTex(128, 16, (g, w, h) => {
    g.fillStyle = '#6b4a3a'; g.fillRect(0, 0, w, h);
    g.fillStyle = '#f6e9d0'; g.font = 'bold 12px "IBM Plex Mono", monospace'; g.textAlign = 'center'; g.textBaseline = 'middle';
    for (let i = 0; i < 8; i++) g.fillText(txt[flip ? 7 - i : i], (i + .5) * 16, h / 2 + 1);
  });
  const files = 'abcdefgh', ranks = '12345678';
  const mkL = (tex, x, z, ry) => { const m = new THREE.Mesh(new THREE.PlaneGeometry(8, 1).rotateX(-Math.PI / 2), mat('#ffffff', { map: tex })); m.position.set(x, BT + .012, z); m.rotation.y = ry; m.scale.set(1, 1, .45); scene.add(m); };
  setTimeout(() => {   // ждём шрифт
    mkL(lblTex(files), 0, 4.4, 0); mkL(lblTex(files, true), 0, -4.4, Math.PI);
    mkL(lblTex(ranks), -4.4, 0, Math.PI / 2); mkL(lblTex(ranks, true), 4.4, 0, -Math.PI / 2);
  }, 600);

  // ---------- гирлянды (лампочки — один InstancedMesh) ----------
  const bulbs = []; const bulbCols = [C.malina, C.myata, C.limonad, '#ffffff', C.malina, C.vasilek];
  const sag = (a, b, n, drop) => { for (let i = 1; i < n; i++) { const t = i / n; bulbs.push([a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t - Math.sin(t * Math.PI) * drop, a[2] + (b[2] - a[2]) * t]); } };
  for (let i = 0; i < 4; i++) { const a = poles[i], b = poles[(i + 1) % 4]; sag([a[0], 3.5, a[1]], [b[0], 3.5, b[1]], 12, .5); }

  // ---------- дома ----------
  const H = new Batch(); const Wn = new Batch();
  const logs = ['#7a5240', '#6b4636', '#85594a'];
  function house(x, z, ry, w = 5, d = 6.5, floors = 2, roofCol = '#3b2c4a') {
    const m = new THREE.Matrix4().makeRotationY(ry).setPosition(x, 0, z);
    const hh = floors * 1.7;
    const loc = (lx, ly, lz) => new THREE.Vector3(lx, ly, lz).applyMatrix4(m);
    for (let i = 0; i < floors * 5; i++) { const p = loc(0, .17 + i * .34, 0); H.box(w, .34, d, logs[i % 3], p.x, p.y, p.z, ry); }
    const r = loc(0, hh, 0); H.geo(prism(w + .8, 1.9, d + .6), roofCol, r.x, r.y, r.z, ry);
    const sn = loc(0, hh + .05, 0); H.geo(prism(w + 1, 2.0, d + .7), '#f4f6fd', sn.x, sn.y + .08, sn.z, ry, 1); // снег
    // окна (светятся)
    for (let f = 0; f < floors; f++) for (const lz of [-d / 2 + 1.2, -.4, d / 2 - 1.2]) for (const sx of [-1, 1]) {
      const p = loc(sx * (w / 2 + .01), .9 + f * 1.7, lz); const on = R() < .8;
      Wn.box(.06, .7, .6, on ? (R() < .5 ? '#ffd27a' : '#ffb35c') : '#3a3352', p.x, p.y, p.z, ry);
    }
    for (const sz of [-1, 1]) { const p = loc(0, .9, sz * (d / 2 + .01)); Wn.box(.7, .7, .06, '#ffcf73', p.x - (sz * 0), p.y + 1.7, p.z, ry); const dp = loc(0, .75, sz * (d / 2 + .02)); H.box(.9, 1.5, .08, '#3b2c4a', dp.x, dp.y, dp.z, ry); }
    // гирлянда по краю крыши
    for (const sx of [-1, 1]) for (let i = 0; i <= 10; i++) { const p = loc(sx * (w / 2 + .35), hh - .05 - Math.sin(i / 10 * Math.PI) * .25, -d / 2 - .2 + i * (d + .4) / 10); bulbs.push([p.x, p.y, p.z]); }
  }
  const houses = [[-13, -14, .5], [12, -15, -.4], [-19, 2, 1.4], [19, 0, -1.5], [-12, 16, 2.6], [13, 17, -2.6]];
  for (const [x, z, ry] of houses) house(x, z, ry);
  // столовая — длинная, одноэтажная
  house(0, -30, Math.PI / 2, 6, 16, 1, '#4a2f3d');

  // ---------- деревья ----------
  const T = new Batch();
  const cone = new THREE.ConeGeometry(1, 1, 7), trunk = new THREE.CylinderGeometry(.18, .22, 1, 5);
  const greens = ['#1f4a43', '#24564b', '#1b3f3c', '#2b5e52'];
  let placed = 0;
  while (placed < 170) {
    const a = R() * Math.PI * 2, d = 11 + Math.pow(R(), .8) * 42; const x = Math.cos(a) * d, z = Math.sin(a) * d;
    if (houses.some(h => Math.hypot(h[0] - x, h[1] - z) < 6) || Math.hypot(x, z + 30) < 10 || Math.hypot(x - 6, z - 52) < 17 || Math.abs(x) < 2 && z > 6) continue;
    if (Math.hypot(x + 8, z + 7) < 4 || Math.hypot(x - 9, z + 8) < 4 || Math.hypot(x, z + 13) < 4) continue;
    const s = .8 + R() * .9, gc = greens[(R() * 4) | 0];
    T.add(trunk, '#4a3128', new THREE.Matrix4().makeScale(s, s, s).setPosition(x, .5 * s, z));
    for (let k = 0; k < 3; k++) {
      const r = (1.5 - k * .38) * s, h = (1.5 - k * .2) * s, y = (1 + k * .95) * s;
      T.add(cone, gc, new THREE.Matrix4().compose(new THREE.Vector3(x, y + h / 2, z), new THREE.Quaternion().setFromEuler(new THREE.Euler(0, R() * 3, 0)), new THREE.Vector3(r, h, r)));
      T.add(cone, '#eef1fb', new THREE.Matrix4().compose(new THREE.Vector3(x, y + h * .78, z), new THREE.Quaternion().setFromEuler(new THREE.Euler(0, R() * 3, 0)), new THREE.Vector3(r * .5, h * .35, r * .5)));
    }
    placed++;
  }
  // сугробы
  const lump = new THREE.SphereGeometry(1, 6, 4);
  for (let i = 0; i < 40; i++) { const a = R() * 6.28, d = 7 + R() * 25; T.add(lump, '#f1f3fb', new THREE.Matrix4().compose(new THREE.Vector3(Math.cos(a) * d, 0, Math.sin(a) * d), new THREE.Quaternion(), new THREE.Vector3(.6 + R() * 1.2, .3 + R() * .4, .6 + R()))); }

  // ---------- костёр ----------
  const fire = new THREE.Vector3(-8, 0, -7);
  for (let i = 0; i < 6; i++) { const a = i / 6 * 6.28; T.box(1.1, .16, .16, '#5a3b2a', fire.x + Math.cos(a) * .3, .15, fire.z + Math.sin(a) * .3, a, 0, .5); }
  for (let i = 0; i < 9; i++) { const a = i / 9 * 6.28; T.box(.3, .22, .3, '#77788a', fire.x + Math.cos(a) * .85, .11, fire.z + Math.sin(a) * .85, a); }
  for (const a of [0, 1.6, 3.2, 4.7]) T.box(1.8, .3, .35, '#6b4a3a', fire.x + Math.cos(a) * 2.4, .3, fire.z + Math.sin(a) * 2.4, -a + Math.PI / 2);  // бревна-лавки
  fireL.position.set(fire.x, 1.4, fire.z);
  const flames = [];
  const fl = new THREE.ConeGeometry(.35, 1, 5);
  for (const [c, s, dx, dz] of [['#ff6a2b', 1, 0, 0], ['#ffb347', .7, .15, .1], ['#ffe66b', .45, -.1, .05], ['#ff4f7b', .55, .05, -.18]]) {
    const f = new THREE.Mesh(fl, new THREE.MeshBasicMaterial({ color: c })); retroize(f.material);
    f.position.set(fire.x + dx, .55 * s + .1, fire.z + dz); f.scale.set(s, s * 1.3, s); scene.add(f); flames.push([f, s, R() * 6]);
  }

  // ---------- баня (дымит) ----------
  const bath = new THREE.Vector3(9, 0, -8);
  T.box(2.4, 1.8, 3.4, '#7a5240', bath.x, 1.25, bath.z, -.6);
  T.geo(prism(2.9, 1, 3.8), '#3b2c4a', bath.x, 2.15, bath.z, -.6); T.geo(prism(3, 1.05, 3.9), '#f4f6fd', bath.x, 2.22, bath.z, -.6);
  for (const [dx, dz] of [[-1, -1.3], [1, -1.3], [-1, 1.3], [1, 1.3]]) {
    const p = new THREE.Vector3(dx, 0, dz).applyAxisAngle(new THREE.Vector3(0, 1, 0), -.6);
    T.geo(new THREE.CylinderGeometry(.38, .38, .2, 8), '#2a1f3d', bath.x + p.x, .38, bath.z + p.z, -.6, 1, 0, Math.PI / 2);
  }
  T.box(.3, 1.2, .3, '#4a4555', bath.x + .5, 3, bath.z - .6);
  Wn.box(.6, .5, .06, '#ffb35c', bath.x + .9 * Math.sin(-.6) * 0 + 1.0, 1.4, bath.z + 1.45, -.6);
  const smoke = [];
  const puffG = new THREE.BoxGeometry(.5, .5, .5);
  for (let i = 0; i < 10; i++) { const p = new THREE.Mesh(puffG, mat('#b9b6c8', { transparent: true, opacity: .7, nocache: true })); scene.add(p); smoke.push([p, i / 10]); }

  // ---------- флаг, билборд, фонари ----------
  T.box(.14, 6, .14, '#cfd3e3', -6.5, 3, 6.5);
  const flagTex = imgTex('data:image/png;base64,', 64);
  const flagG = new THREE.PlaneGeometry(2.2, 1.5, 8, 2);
  const flagBase = flagG.attributes.position.array.slice();
  const flagM = mat(C.bak, { map: null, side: THREE.DoubleSide, nocache: true });
  const flagBg = canvasTex(64, 44, (g) => { g.fillStyle = C.bak; g.fillRect(0, 0, 64, 44); });
  flagM.map = flagBg;
  const flag = new THREE.Mesh(flagG, flagM); flag.position.set(-6.5 + 1.1, 5.2, 6.5); scene.add(flag);
  const im = new Image(); im.onload = () => { const c = flagBg.image, g = c.getContext('2d'); g.drawImage(im, 12, 2, 40, 40); flagBg.needsUpdate = true; }; im.src = 'data:image/png;base64,';

  const bb = new Batch();
  bb.box(.25, 3.4, .25, woodD, -3.1, 1.7, -13); bb.box(.25, 3.4, .25, woodD, 3.1, 1.7, -13); bb.box(6.8, 3.6, .2, '#2a1f3d', 0, 3.9, -13.1);
  scene.add(bb.build(vmat));
  const logoTex = imgTex('data:image/png;base64,', 256);
  const logo = new THREE.Mesh(new THREE.PlaneGeometry(4.9, 3.18), new THREE.MeshBasicMaterial({ map: logoTex, transparent: true, alphaTest: .3 }));
  retroize(logo.material); logo.position.set(0, 3.9, -12.98); scene.add(logo);

  const lamps = [[-2.2, 9], [2.2, 13], [-2.2, 17], [6, -10], [-5, -11], [0, -20]];
  for (const [x, z] of lamps) { T.box(.12, 2.6, .12, '#2a1f3d', x, 1.3, z); Wn.box(.34, .34, .34, '#ffe2a6', x, 2.75, z); }

  scene.add(T.build(vmat)); scene.add(H.build(vmat)); scene.add(Wn.build(glow));

  // лампочки
  const bulbMesh = new THREE.InstancedMesh(new THREE.BoxGeometry(.09, .12, .09), retroize(new THREE.MeshBasicMaterial({ color: '#ffffff' })), bulbs.length);
  const tmp = new THREE.Object3D(); const bc = new THREE.Color();
  bulbs.forEach((b, i) => { tmp.position.set(...b); tmp.updateMatrix(); bulbMesh.setMatrixAt(i, tmp.matrix); bulbMesh.setColorAt(i, bc.set(bulbCols[i % bulbCols.length])); });
  scene.add(bulbMesh);

  // ---------- снег ----------
  const N = 1400, sp = new Float32Array(N * 3);
  for (let i = 0; i < N; i++) { sp[i * 3] = (R() - .5) * 40; sp[i * 3 + 1] = R() * 16; sp[i * 3 + 2] = (R() - .5) * 40; }
  const sg = new THREE.BufferGeometry(); sg.setAttribute('position', new THREE.BufferAttribute(sp, 3));
  const snow = new THREE.Points(sg, new THREE.PointsMaterial({ color: '#ffffff', size: .045, sizeAttenuation: true, transparent: true, opacity: .9 }));
  scene.add(snow);

  // ---------- обновление ----------
  const world = {
    fire, bath, dark: 0,
    update(t, dt) {
      for (const [f, s, ph] of flames) { const k = 1 + Math.sin(t * 13 + ph) * .12 + Math.sin(t * 7.3 + ph * 2) * .08; f.scale.set(s * (1.05 - (k - 1)), s * 1.3 * k, s); f.rotation.y = t * 2 + ph; }
      fireL.intensity = (22 + Math.sin(t * 17) * 3 + Math.sin(t * 7) * 3) * (1 - world.dark * .3);
      for (const s of smoke) { const [p, o] = s; const k = (t * .18 + o) % 1; p.position.set(bath.x + .5 + Math.sin(k * 6 + o * 9) * .4 * k, 3.6 + k * 4.5, bath.z - .6 - k * 1.2); p.scale.setScalar(.4 + k * 1.6); p.material.opacity = .65 * (1 - k); p.rotation.set(k * 2, k * 3, 0); }
      const a = sg.attributes.position.array;
      for (let i = 0; i < N; i++) { a[i * 3 + 1] -= dt * (.6 + (i % 7) * .08); a[i * 3] += Math.sin(t + i) * dt * .15; if (a[i * 3 + 1] < 0) a[i * 3 + 1] += 16; }
      sg.attributes.position.needsUpdate = true;
      for (let i = 0; i < bulbs.length; i++) {
        const on = ((Math.floor(t * 2.2) + i) % 3) !== 0;
        bulbMesh.setColorAt(i, bc.set(bulbCols[i % bulbCols.length]).multiplyScalar(on ? 1 : .25));
      }
      bulbMesh.instanceColor.needsUpdate = true;
      const fp = flagG.attributes.position;
      for (let i = 0; i < fp.count; i++) { const x = flagBase[i * 3] + 1.1; fp.setZ(i, Math.sin(x * 2.4 - t * 4) * .14 * x / 2.2); }
      fp.needsUpdate = true;
      const L = 1 - world.dark * .55; boardL1.intensity = 16 * L; boardL2.intensity = 16 * L;
    },
  };
  return world;
}
